    // Row handlers (side effects only — notifiers drive the rebuild).
    // -------------------------------------------------------------------------
    void cycleScreen() {
      const order = [
        ScreenType.spectrum,
        ScreenType.polo,
        ScreenType.dot,
        ScreenType.void_,
        ScreenType.cassette,
